import heapq

def match(orders):
    trades = []
    order_info = {}  # id -> {'side','price','qty','time','active'}
    buy_heap = []    # entries: (-price, time, id)
    sell_heap = []   # entries: (price, time, id)
    time_counter = 0

    for o in orders:
        type_ = o[0]

        if type_ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if type_ == 'limit':
            _, oid, side, price, qty = o
        elif type_ == 'ioc':
            _, oid, side, price, qty = o
        elif type_ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        time_counter += 1
        info = {'side': side, 'price': price, 'qty': qty, 'time': time_counter, 'active': True}
        order_info[oid] = info

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            if not opp_heap:
                break

            if side == 'buy':
                top_price, top_time, top_id = opp_heap[0]
            else:
                neg_price, top_time, top_id = opp_heap[0]
                top_price = -neg_price

            top_info = order_info.get(top_id)
            if top_info is None or not top_info['active'] or top_info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if type_ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            # pop it, we will trade against it
            heapq.heappop(opp_heap)

            trade_qty = min(remaining, top_info['qty'])
            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            top_info['qty'] -= trade_qty

            if top_info['qty'] == 0:
                top_info['active'] = False
            else:
                if side == 'buy':
                    heapq.heappush(opp_heap, (top_price, top_time, top_id))
                else:
                    heapq.heappush(opp_heap, (-top_price, top_time, top_id))

        info['qty'] = remaining

        if type_ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, time_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, time_counter, oid))
        else:
            # fully filled limit order, or leftover ioc/market order (discarded)
            info['active'] = False

    return trades

